package local.velo.bridge;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import java.io.*;
public final class BoardPreviewTest extends Instrumentation {
 int checks;MainActivity app;void check(boolean v,String text)throws Exception{checks++;if(!v)throw new Exception(text);}void main(Runnable r){runOnMainSync(r);}public void onCreate(Bundle b){super.onCreate(b);start();}
 Bitmap render()throws Exception{final Bitmap[] image=new Bitmap[1];main(()->{image[0]=Bitmap.createBitmap(270,480,Bitmap.Config.ARGB_8888);app.boardPreview.measure(View.MeasureSpec.makeMeasureSpec(270,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(480,View.MeasureSpec.EXACTLY));app.boardPreview.layout(0,0,270,480);app.boardPreview.draw(new Canvas(image[0]));});return image[0];}
 void frame(String value){DeviceLinkService.lastSent=value;DeviceLinkService.sentAt=SystemClock.elapsedRealtime();}
 public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();c.stopService(new Intent(c,RideService.class));c.stopService(new Intent(c,DeviceLinkService.class));c.getSharedPreferences("navigation",0).edit().remove("device_address").commit();app=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));main(()->app.showTab("device"));check(app.boardPreviewGroup.getVisibility()==View.GONE,"disconnected preview hidden");RideService.connected=true;frame("D,23.5,1.25,600,L,120\nH,42,G,0,L,120,2300,200,90,0,2,1,64,92,80,30,1\nB,42,1,20,20,90,100,2\nT,42,2,5\n");Thread.sleep(1400);check(app.boardPreviewGroup.getVisibility()==View.VISIBLE,"preview appears automatically on connect");Bitmap map=render();check(app.boardPreview.map,"actual H protocol parsed");check(app.boardPreview.route.size()==1&&app.boardPreview.roads.size()==1,"route and surroundings share sent frame");check(app.boardPreview.phase==2&&app.boardPreview.turn=='L'&&app.boardPreview.meters==120,"turn phase and distance synchronized");check(app.boardPreview.speed==23.5&&app.boardPreview.seconds==600&&app.boardPreview.trip==1.25,"actual metrics synchronized");check(map.getPixel(130,240)!=Color.WHITE,"board layout renders");main(()->app.boardPreview.page(true));Bitmap stats=render();check(!stats.sameAs(map),"statistics preview switches layout");check(app.boardPreview.stats,"preview page local state");main(()->app.boardPreview.page(false));frame("D,0.0,1.25,601,N,-1\nGPSWAIT\n");Bitmap waiting=render();check(app.boardPreview.gpsWait&&!app.boardPreview.map&&app.boardPreview.route.isEmpty(),"GPS loss removes stale route");check(!waiting.sameAs(map),"GPS wait visually distinct");frame("D,0.0,1.25,602,N,-1\nMAPOFF\n");render();check(!app.boardPreview.gpsWait&&!app.boardPreview.map,"standby does not claim GPS loss");app.boardPreview.parse("H,42,G,0,L,120,2300,200,90,0,2,2,64,92,80,30,1\n");check(!app.boardPreview.map,"partial packet cannot render partial map");DeviceLinkService.sentAt=SystemClock.elapsedRealtime()-6000;Bitmap stale=render();check(!stale.sameAs(map),"expired transmission cannot appear live");RideService.connected=false;Thread.sleep(1400);check(app.boardPreviewGroup.getVisibility()==View.GONE,"disconnect hides preview automatically");RideService.connected=true;frame("D,23.5,1.25,600,L,120\nH,42,G,0,L,120,2300,200,90,0,2,1,64,92,80,30,1\nB,42,1,20,20,90,100,2\nT,42,9,5\n");render();check(app.boardPreview.title().equals("GPS FIX OK")&&app.boardPreview.detail().equals("MOVE TO SET"),"valid stationary GPS keeps correct instruction");main(()->app.renderDevice());Thread.sleep(500);try(OutputStream file=new FileOutputStream(new File(c.getExternalFilesDir(null),"board-preview-test.png"))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,file);}out.putString("checks",checks+" board preview synchronization and lifecycle checks passed");finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("error",e.toString());finish(Activity.RESULT_CANCELED,out);}finally{RideService.connected=false;DeviceLinkService.lastSent=null;}}
}
